SELECT DATE_FORMAT(u.created_at, '%Y-%m-%d') AS date_label, COUNT(u.user_id) AS signup_count FROM users u
JOIN user_roles ur ON u.user_id = ur.user_id JOIN roles r ON ur.role_id = r.role_id
r.role = #{roleName}
AND u.created_at >= #{startDate} AND u.created_at < #{endDate}
GROUP BY date_label ORDER BY date_label ASC

SELECT 'all_time' AS date_label, COUNT(u.user_id) AS signup_count FROM users u
JOIN user_roles ur ON u.user_id = ur.user_id JOIN roles r ON ur.role_id = r.role_id
r.role = #{roleName}
